import asyncio
import contextlib
import time
from typing import TYPE_CHECKING, Any, Awaitable, Callable, Dict, List

import structlog
from a2a.types import DataPart, FilePart, FileWithUri, Part, Task, TaskState, TextPart
from pydantic import ValidationError

from rasa.agents.constants import (
    AGENT_METADATA_SENDER_ID_KEY,
    ASYNC_AGENT_PROCESSING_TIMEOUT_SECONDS,
)
from rasa.core.lock_store import LockStore
from rasa.core.tracker_stores.tracker_store import TrackerStore
from rasa.dialogue_understanding.stack.frames.flow_stack_frame import (
    AgentState,
)
from rasa.shared.core.constants import (
    ACTION_METADATA_MESSAGE_KEY,
    ACTION_METADATA_TEXT_KEY,
)

if TYPE_CHECKING:
    from rasa.core.processor import MessageProcessor
    from rasa.shared.core.trackers import DialogueStateTracker

logger = structlog.get_logger(__name__)


class InvalidAsyncTaskUpdateError(ValueError):
    """Raised when `/agent/task_update` receives an invalid payload."""


class AsyncTaskResultProcessor:
    """Process async A2A task updates from push notifications.

    Updates are queued per-conversation and processed sequentially to
    maintain ordering.
    """

    def __init__(
        self,
        lock_store: LockStore,
        tracker_store: TrackerStore,
        processor: "MessageProcessor",
        on_task_updated: Callable[[str, str], Awaitable[None]] | None = None,
    ) -> None:
        """Initialize the processor with dependencies for persisting task updates."""
        self.lock_store = lock_store
        self.tracker_store = tracker_store
        self.processor = processor
        self.on_task_updated = on_task_updated
        self._task_update_queues: dict[str, asyncio.Queue[Task]] = {}
        self._queue_processor_tasks: dict[str, asyncio.Task[None]] = {}

    async def stop(self) -> None:
        """Cancel all background queue processors and drop any pending updates."""
        queue_processor_tasks = list(self._queue_processor_tasks.values())
        for task in queue_processor_tasks:
            task.cancel()
        for task in queue_processor_tasks:
            with contextlib.suppress(asyncio.CancelledError):
                await task
        self._task_update_queues.clear()

        # shutdown: OK to drop any remaining tasks in the queues
        self._queue_processor_tasks.clear()

    async def process_push_notification(self, result: Dict[str, Any]) -> bool:
        """Entry point for push notifications.

        Validates payload and enqueues task update for async processing.
        """
        agent_task = self._parse_task_update(result)
        conversation_id = self._conversation_id_from_task(agent_task)
        if not conversation_id:
            logger.error(
                "async_task_result.process_push_notification.missing_conversation_id",
                task_id=agent_task.id,
            )
            return False

        self._enqueue_task_update(conversation_id, agent_task)
        return True

    def _parse_task_update(self, result: Dict[str, Any]) -> Task:
        """Parse and validate the incoming task update payload.

        Raises InvalidAsyncTaskUpdateError if malformed.
        """
        if not isinstance(result, dict):
            raise InvalidAsyncTaskUpdateError(
                "Task update payload must be a JSON object."
            )

        if result.get("kind") != "task":
            raise InvalidAsyncTaskUpdateError(
                "Task update payload must have kind='task'."
            )

        try:
            agent_task = Task(**result)
        except ValidationError as e:
            raise InvalidAsyncTaskUpdateError(
                f"Invalid A2A task update payload: {e}"
            ) from e

        if not agent_task.id:
            raise InvalidAsyncTaskUpdateError(
                "Task update payload must include a task id."
            )

        conversation_id = self._conversation_id_from_task(agent_task)
        if not conversation_id:
            raise InvalidAsyncTaskUpdateError(
                "Task update payload must include sender_id in task metadata."
            )

        return agent_task

    async def _persist_task_update(self, agent_task: Task) -> bool:
        """Lock conversation and persist task update.

        Retrieves tracker, updates agent frame state, and persists to store.
        """
        conversation_id = self._conversation_id_from_task(agent_task)

        if not conversation_id:
            logger.error(
                "async_task_result.persist_task_update.missing_conversation_id",
                task_id=agent_task.id,
            )
            return False

        logger.info(
            "async_task_result.process_async_task_result",
            conversation_id=conversation_id,
            task_id=agent_task.id,
            task_status=agent_task.status.state,
        )

        updated = False
        async with self.lock_store.lock(conversation_id, wait_time_in_seconds=1):
            tracker = await self.tracker_store.retrieve(conversation_id)
            if not tracker:
                logger.debug(
                    "async_task_result.process_async_task_result.tracker_not_found",
                    conversation_id=conversation_id,
                )
                return False

            if self._update_tracker_with_task(tracker, agent_task) is None:
                return False

            await self.processor.save_tracker(tracker)
            updated = True

        return updated

    def _enqueue_task_update(self, conversation_id: str, agent_task: Task) -> None:
        """Add task to conversation queue.

        Starts a background processor if not already running.
        """
        queue = self._task_update_queues.get(conversation_id)
        if queue is None:
            queue = asyncio.Queue()
            self._task_update_queues[conversation_id] = queue

        queue.put_nowait(agent_task)

        current_task = self._queue_processor_tasks.get(conversation_id)
        if current_task is not None and not current_task.done():
            return

        task: asyncio.Task[None] = asyncio.create_task(
            self._process_task_update_queue(conversation_id)
        )
        self._queue_processor_tasks[conversation_id] = task

        def _cleanup(done_task: asyncio.Task[None]) -> None:
            if self._queue_processor_tasks.get(conversation_id) is done_task:
                self._queue_processor_tasks.pop(conversation_id, None)
            with contextlib.suppress(asyncio.CancelledError):
                exc = done_task.exception()
                if exc is not None:
                    logger.error(
                        "async_task_result.process_task_update_queue.error",
                        conversation_id=conversation_id,
                        error=str(exc),
                        exc_info=exc,
                    )

        task.add_done_callback(_cleanup)

    async def _process_task_update_queue(self, conversation_id: str) -> None:
        """Background worker that drains queue for a single conversation.

        Ensures sequential processing.
        """
        queue = self._task_update_queues[conversation_id]

        if queue is None:
            logger.error(
                "async_task_result.process_task_update_queue.no_queue",
                conversation_id=conversation_id,
            )
            return

        while True:
            try:
                agent_task = queue.get_nowait()
            except asyncio.QueueEmpty:
                self._task_update_queues.pop(conversation_id, None)
                return

            try:
                updated = await self._persist_task_update(agent_task)
                if updated:
                    await self._notify_task_updated(conversation_id, agent_task.id)
            except Exception as e:
                logger.error(
                    "async_task_result.process_task_update.error",
                    conversation_id=conversation_id,
                    task_id=agent_task.id,
                    error=str(e),
                    exc_info=e,
                )
            finally:
                queue.task_done()

    async def _notify_task_updated(self, conversation_id: str, task_id: str) -> None:
        """Invoke the on_task_updated callback hook if provided.

        Allows external notification of state changes.
        """
        if self.on_task_updated is None:
            return

        try:
            await self.on_task_updated(conversation_id, task_id)
        except Exception as e:
            logger.error(
                "async_task_result.on_task_updated.error",
                conversation_id=conversation_id,
                task_id=task_id,
                error=str(e),
                exc_info=e,
            )

    @staticmethod
    def _conversation_id_from_task(agent_task: Task) -> str | None:
        """Extract the conversation ID from task metadata."""
        if not agent_task.metadata:
            return None
        conversation_id = agent_task.metadata.get(AGENT_METADATA_SENDER_ID_KEY)
        return str(conversation_id) if conversation_id else None

    def _update_tracker_with_task(
        self, tracker: "DialogueStateTracker", agent_task: Task
    ) -> bool | None:
        """Map A2A task state to agent frame state and update the tracker stack."""
        agent_frame = tracker.stack.find_agent_stack_frame_by_task_id(agent_task.id)

        if not agent_frame:
            logger.debug(
                "async_task_result.process_async_task_result.agent_frame_not_found",
                agent_task_id=agent_task.id,
            )
            return None

        top_frame = tracker.stack.top()
        if agent_frame != top_frame:
            logger.debug(
                "async_task_result.process_async_task_result.agent_frame_not_on_stack_top",
                task_id=agent_task.id,
                top_frame_name=type(top_frame) if top_frame else None,
            )

        if agent_task.status.state == TaskState.working:
            agent_frame.state = AgentState.PROCESSING
            agent_frame.processing_deadline = (
                time.time() + ASYNC_AGENT_PROCESSING_TIMEOUT_SECONDS
            )
            self._set_message_metadata(agent_frame, agent_task)
        elif agent_task.status.state == TaskState.input_required:
            agent_frame.state = AgentState.WAITING_FOR_INPUT_FROM_PUSH_NOTIFICATION
            agent_frame.processing_deadline = None
            self._set_message_metadata(agent_frame, agent_task)
        elif agent_task.status.state == TaskState.completed:
            agent_frame.state = AgentState.COMPLETED
            agent_frame.processing_deadline = None
            if agent_task.status.message and agent_task.status.message.parts:
                self._set_message_metadata(agent_frame, agent_task)
            else:
                agent_frame.metadata = agent_frame.metadata or {}
                agent_frame.metadata[ACTION_METADATA_MESSAGE_KEY] = None
        elif agent_task.status.state in {
            TaskState.auth_required,
            TaskState.canceled,
            TaskState.rejected,
            TaskState.failed,
        }:
            agent_frame.state = AgentState.TERMINAL
            agent_frame.processing_deadline = None
            self._set_message_metadata(agent_frame, agent_task)
        else:
            logger.debug(
                "async_task_result.process_async_task_result.unsupported_task_state",
                task_id=agent_task.id,
                task_status=agent_task.status.state,
            )
            return None

        stack = tracker.stack
        stack.update_agent_stack_frame(agent_frame)
        tracker.update_stack(stack)
        return True

    def _set_message_metadata(self, agent_frame: Any, agent_task: Task) -> None:
        """Extract message from task status.

        Stores it in agent frame metadata for later rendering.
        """
        agent_frame.metadata = agent_frame.metadata or {}
        message = agent_frame.metadata.get(ACTION_METADATA_MESSAGE_KEY, {})
        if agent_task.status.message:
            message[ACTION_METADATA_TEXT_KEY] = (
                self._generate_response_message_from_parts(
                    agent_task.status.message.parts
                )
            )
        agent_frame.metadata[ACTION_METADATA_MESSAGE_KEY] = message

    @staticmethod
    def _generate_response_message_from_parts(parts: List[Part]) -> str:
        """Convert A2A message parts to a single string.

        Extracts text and file URIs while skipping data parts.
        """
        result = ""
        if not parts:
            return result
        for part in parts:
            if isinstance(part.root, TextPart):
                result += part.root.text + "\n"
            elif isinstance(part.root, DataPart):
                # DataPart results will be returned as a part of the structured results,
                # we don't need to include it in the response message
                continue
            elif isinstance(part.root, FilePart) and isinstance(
                part.root.file, FileWithUri
            ):
                # If the file is a FileWithUri, we can include the URI
                result += f"File: {part.root.file.uri}\n"
            else:
                logger.warning(
                    "async_task_result._parts_to_single_message.warning",
                    event_info="Unsupported part type encountered",
                    part_type=type(part.root),
                )
        return result.strip()
